      "unity/Depth.Desktop/Assets/Scripts/DepthDesktop.cs(16,107): error CS0246: \u0027Color\u0027 \uD615\uC2DD \uB610\uB294 \uB124\uC784\uC2A4\uD398\uC774\uC2A4 \uC774\uB984\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. using \uC9C0\uC2DC\uBB38 \uB610\uB294 \uC5B4\uC148\uBE14\uB9AC \uCC38\uC870\uAC00 \uC788\uB294\uC9C0 \uD655\uC778\uD558\uC138\uC694.",
      "unity/Depth.Desktop/Assets/Scripts/DepthDesktop.cs(24,50): error CS0246: \u0027GameObject\u0027 \uD615\uC2DD \uB610\uB294 \uB124\uC784\uC2A4\uD398\uC774\uC2A4 \uC774\uB984\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. using \uC9C0\uC2DC\uBB38 \uB610\uB294 \uC5B4\uC148\uBE14\uB9AC \uCC38\uC870\uAC00 \uC788\uB294\uC9C0 \uD655\uC778\uD558\uC138\uC694.",
